-- Database: `kbbi` (High Quality Validated Synonyms v3)
-- Table structure for table `dictionary_sinonim`

CREATE TABLE IF NOT EXISTS `dictionary_sinonim` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kata_a` varchar(100) NOT NULL,
  `kata_b` varchar(100) NOT NULL,
  `penjelasan` text NOT NULL,
  `penggunaan_a` text DEFAULT NULL,
  `penggunaan_b` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;









































